using System.Globalization;
using System.Text;
namespace GpuPro.Windows;
internal sealed class FrameCsvReader {
 string source="",partial="";long offset;int column=-1;bool fps;readonly Queue<double> times=new();
 internal double[] Samples{get;private set;}=Array.Empty<double>();
 static string[] Fields(string line){var cells=new List<string>();var text=new StringBuilder();bool quoted=false;for(int i=0;i<line.Length;i++){char c=line[i];if(c=='"'){if(quoted&&i+1<line.Length&&line[i+1]=='"'){text.Append('"');i++;}else quoted=!quoted;}else if(c==','&&!quoted){cells.Add(text.ToString().Trim());text.Clear();}else text.Append(c);}cells.Add(text.ToString().Trim());return cells.ToArray();}
 void Line(string line){var fields=Fields(line.TrimStart('\uFEFF'));int frame=Array.FindIndex(fields,s=>s.Equals("frametime",StringComparison.OrdinalIgnoreCase)||s.Equals("MsBetweenPresents",StringComparison.OrdinalIgnoreCase));int rate=Array.FindIndex(fields,s=>s.Equals("fps",StringComparison.OrdinalIgnoreCase));if(frame>=0||rate>=0){column=frame>=0?frame:rate;fps=frame<0;times.Clear();return;}if(column<0||column>=fields.Length)return;if(double.TryParse(fields[column],NumberStyles.Float,CultureInfo.InvariantCulture,out double n)&&double.IsFinite(n)&&n>0){double ms=fps?1000/n:n;if(ms>10000)return;times.Enqueue(ms);if(times.Count>240)times.Dequeue();}}
 void Reset(){offset=0;partial="";column=-1;fps=false;times.Clear();}
 internal Native.Frames Read(string path){try{var info=new FileInfo(path);if(!info.Exists||DateTime.UtcNow-info.LastWriteTimeUtc>TimeSpan.FromSeconds(3)){Reset();Samples=Array.Empty<double>();return default;}if(source!=info.FullName||info.Length<offset){Reset();source=info.FullName;}using var stream=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.ReadWrite|FileShare.Delete);if(offset==0&&stream.Length>512*1024){var header=new byte[65536];int count=stream.Read(header);var lines=Encoding.UTF8.GetString(header,0,count).Split('\n');foreach(var line in lines){Line(line);if(column>=0)break;}stream.Position=Math.Max(count,stream.Length-512*1024);using var skip=new StreamReader(stream,Encoding.UTF8,false,4096,true);skip.ReadLine(); // discard a partial first row; reopen at the exact byte boundary below
 stream.Position=Math.Max(count,stream.Length-512*1024);int c;while((c=stream.ReadByte())>=0&&c!=10){}offset=stream.Position;}
 stream.Position=offset;int size=(int)Math.Min(stream.Length-offset,4*1024*1024);var bytes=new byte[size];int read=stream.Read(bytes);offset+=read;var text=partial+Encoding.UTF8.GetString(bytes,0,read);int last=text.LastIndexOf('\n');if(last>=0){foreach(var line in text[..last].Split('\n'))Line(line.TrimEnd('\r'));partial=text[(last+1)..];}else partial=text;if(partial.Length>65536)throw new InvalidDataException("Linha CSV grande demais");Samples=times.ToArray();return Native.gpp_frame_stats(Samples,Samples.Length);}catch{Reset();Samples=Array.Empty<double>();return default;}}
}
